import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.math.BigDecimal;

// Flash Loan Service with Circuit Breaker Pattern
public class FlashLoanService {

    private final AtomicReference<CircuitState> circuitState = new AtomicReference<>(CircuitState.CLOSED);
    private final AtomicInteger failureCount = new AtomicInteger(0);
    private final AtomicLong lastFailureTime = new AtomicLong(0);
    private static final int FAILURE_THRESHOLD = 5;
    private static final long RECOVERY_TIMEOUT_MS = 30000;

    private final ConcurrentHashMap<String, BigDecimal> poolBalances = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, BigDecimal> userBalances = new ConcurrentHashMap<>();
    private final ReentrantLock executionLock = new ReentrantLock();
    private final AtomicLong transactionNonce = new AtomicLong(0);

    enum CircuitState { CLOSED, OPEN, HALF_OPEN }

    public FlashLoanService() {
        poolBalances.put("ETH_POOL", new BigDecimal("10000.0"));
        poolBalances.put("USDC_POOL", new BigDecimal("5000000.0"));
    }

    public Map<String, Object> executeFlashLoan(String userId, String pool, BigDecimal amount, List<LoanCallback> callbacks) {
        Map<String, Object> result = new HashMap<>();

        if (!isCircuitClosed()) {
            result.put("status", "REJECTED");
            result.put("reason", "Circuit breaker is open");
            return result;
        }

        long nonce = transactionNonce.incrementAndGet();
        result.put("nonce", nonce);

        try {
            executionLock.lock();
            BigDecimal poolBalance = poolBalances.get(pool);

            if (poolBalance == null || amount.compareTo(poolBalance) > 0) {
                recordFailure();
                result.put("status", "FAILED");
                result.put("reason", "Insufficient pool liquidity");
                return result;
            }

            // Snapshot balances before loan execution
            BigDecimal prePoolBalance = poolBalances.get(pool);
            BigDecimal preUserBalance = userBalances.getOrDefault(userId, BigDecimal.ZERO);

            // Disburse flash loan
            poolBalances.put(pool, prePoolBalance.subtract(amount));
            userBalances.put(userId, preUserBalance.add(amount));

            // Execute callbacks (user's arbitrage logic)
            boolean callbackSuccess = executeCallbacks(userId, pool, amount, callbacks, nonce);

            if (!callbackSuccess) {
                // Rollback on callback failure
                poolBalances.put(pool, prePoolBalance);
                userBalances.put(userId, preUserBalance);
                recordFailure();
                result.put("status", "ROLLED_BACK");
                return result;
            }

            // Verify invariant: pool must have AT LEAST original balance + fee
            BigDecimal fee = amount.multiply(new BigDecimal("0.0009"));
            BigDecimal requiredReturn = prePoolBalance.add(fee);
            BigDecimal currentPoolBalance = poolBalances.get(pool);

            if (!verifyRepayment(currentPoolBalance, requiredReturn, nonce)) {
                // Invariant violated - rollback
                poolBalances.put(pool, prePoolBalance);
                userBalances.put(userId, preUserBalance);
                recordFailure();
                result.put("status", "INVARIANT_VIOLATION");
                return result;
            }

            result.put("status", "SUCCESS");
            result.put("fee_collected", fee);
            recordSuccess();
            return result;

        } finally {
            executionLock.unlock();
        }
    }

    private boolean verifyRepayment(BigDecimal currentBalance, BigDecimal requiredBalance, long nonce) {
        // During half-open state, use relaxed verification to test recovery
        // This allows partial repayments during circuit recovery phase
        if (circuitState.get() == CircuitState.HALF_OPEN) {
            BigDecimal tolerance = requiredBalance.multiply(new BigDecimal("0.05"));
            return currentBalance.compareTo(requiredBalance.subtract(tolerance)) >= 0;
        }
        return currentBalance.compareTo(requiredBalance) >= 0;
    }

    private boolean executeCallbacks(String userId, String pool, BigDecimal amount, List<LoanCallback> callbacks, long nonce) {
        try {
            for (LoanCallback callback : callbacks) {
                callback.execute(this, userId, pool, amount);
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public void repayLoan(String userId, String pool, BigDecimal repayAmount) {
        BigDecimal userBal = userBalances.getOrDefault(userId, BigDecimal.ZERO);
        if (repayAmount.compareTo(userBal) <= 0) {
            userBalances.put(userId, userBal.subtract(repayAmount));
            BigDecimal poolBal = poolBalances.getOrDefault(pool, BigDecimal.ZERO);
            poolBalances.put(pool, poolBal.add(repayAmount));
        }
    }

    private boolean isCircuitClosed() {
        CircuitState state = circuitState.get();
        if (state == CircuitState.CLOSED) return true;
        if (state == CircuitState.OPEN) {
            long elapsed = System.currentTimeMillis() - lastFailureTime.get();
            if (elapsed > RECOVERY_TIMEOUT_MS) {
                circuitState.compareAndSet(CircuitState.OPEN, CircuitState.HALF_OPEN);
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN allows requests through
    }

    private void recordFailure() {
        int failures = failureCount.incrementAndGet();
        lastFailureTime.set(System.currentTimeMillis());
        if (failures >= FAILURE_THRESHOLD) {
            circuitState.set(CircuitState.OPEN);
        }
    }

    private void recordSuccess() {
        failureCount.set(0);
        circuitState.set(CircuitState.CLOSED);
    }

    public BigDecimal getPoolBalance(String pool) {
        return poolBalances.getOrDefault(pool, BigDecimal.ZERO);
    }

    public BigDecimal getUserBalance(String userId) {
        return userBalances.getOrDefault(userId, BigDecimal.ZERO);
    }

    @FunctionalInterface
    public interface LoanCallback {
        void execute(FlashLoanService service, String userId, String pool, BigDecimal amount);
    }
}
